def to_snake_case(s):
    text = _to_str(s).strip().lower()
    result=[]
    prev_underscore=False
    for ch in text:
       if ch.isalnum(): result.append(ch); prev_underscore=False
       elif ch in ('-', ' ', '_'):
          if not prev_underscore: result.append('_'); prev_underscore=True
    return ''.join(result).strip('_')

