def truncate_string(s, max_length, ellipsis="..."):
    text=_to_str(s); ell=_to_str(ellipsis); max_length=int(max_length)
    if max_length <=0: return ""
    if len(text) <= max_length: return text
    if max_length <= len(ell): return text[:max_length]
    return text[:max_length-len(ell)] + ell

